import sys

def process_test_case(n, k, s):
    # Count occurrences of each character
    count = [0] * 26
    for char in s:
        count[ord(char) - ord('a')] += 1

    # Initialize the result string
    result = list(s)

    # Perform operations
    for i in range(25):
        if k == 0:
            break
        if count[i] > 0:
            replace_count = min(count[i], k)
            k -= replace_count
            for j in range(n):
                if result[j] == chr(ord('a') + i):
                    result[j] = chr(ord('a') + i - 1)
            count[i] -= replace_count
            count[i - 1] += replace_count

    return ''.join(result)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        s = data[index + 2]
        index += 3
        results.append(process_test_case(n, k, s))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
